/* ============================================================================
   Talento_Humano.sql — script único de creación desde cero.

   Compatibilidad: SQL Server 2014 en adelante. COMPATIBILITY_LEVEL = 120;
   sin opciones de BD introducidas después de 2014 (QUERY_STORE requiere
   2016+, ACCELERATED_DATABASE_RECOVERY requiere 2019+, LEDGER requiere
   2022+, OPTIMIZE_FOR_SEQUENTIAL_KEY es opción de índice 2019+ — ninguna
   se usa aquí). Sin ruta de archivo fija (usa las rutas de datos por
   defecto configuradas en el SQL Server donde corra) ni nombre de
   instancia hardcodeado — corre en cualquier computador.

   ¡ATENCIÓN! Este script hace DROP + CREATE de la base Talento_Humano —
   borra todos los datos existentes antes de recrearla con el esquema y
   los datos completos de abajo. Pensado para instalar/reinstalar desde
   cero; NO correr sobre una base en producción con datos que quieras
   conservar sin respaldo previo.
   ============================================================================ */

USE [master]
GO
IF EXISTS (SELECT name FROM sys.databases WHERE name = N'Talento_Humano')
BEGIN
    ALTER DATABASE [Talento_Humano] SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE [Talento_Humano];
END
GO
CREATE DATABASE [Talento_Humano] COLLATE Modern_Spanish_CI_AS;
GO
ALTER DATABASE [Talento_Humano] SET COMPATIBILITY_LEVEL = 120
GO
IF (1 = FULLTEXTSERVICEPROPERTY('IsFullTextInstalled'))
begin
EXEC [Talento_Humano].[dbo].[sp_fulltext_database] @action = 'enable'
end
